import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'orbit-product-hero';

  const timelines = [];
  const cleanups = [];

  // Build backdrop plane with engineered vertical gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    color: new THREE.Color('#0b0b10'),
    emissive: new THREE.Color('#000000'),
    metalness: 0,
    roughness: 1,
    side: THREE.DoubleSide
  });

  // TSL gradient from #0b0b10 (0.0) → #101017 (0.55) → #16161d (1.0)
  const gradTop = new THREE.Color('#16161d');
  const gradMid = new THREE.Color('#101017');
  const gradBot = new THREE.Color('#0b0b10');
  const uvNode = uv();
  const vY = uvNode.y;
  const gradNode = mix(
    mix(gradBot, gradMid, smoothstep(0, 0.55, vY)),
    gradTop,
    smoothstep(0.55, 1, vY)
  );
  backdropMat.colorNode = gradNode;

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Contact shadow plane (radial gradient)
  const shadowGeo = new THREE.CircleGeometry(1.6, 64);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -1.1, 0.1);
  shadowMesh.scale.set(1, 1, 1);

  // Radial falloff on shadow (encode as vertex color or use shader)
  const shadowPositions = shadowGeo.attributes.position.array;
  const shadowColors = new Float32Array(shadowPositions.length);
  for (let i = 0; i < shadowPositions.length; i += 3) {
    const x = shadowPositions[i];
    const y = shadowPositions[i + 1];
    const dist = Math.sqrt(x * x + y * y) / 1.6;
    const fade = Math.max(0, 1 - dist * dist);
    shadowColors[i] = fade * 0.55;
    shadowColors[i + 1] = fade * 0.55;
    shadowColors[i + 2] = fade * 0.55;
  }
  shadowGeo.setAttribute('color', new THREE.BufferAttribute(shadowColors, 1));
  shadowMat.map = null;
  shadowMat.opacity = 0.55;
  group.add(shadowMesh);

  // Plinth (low cylinder)
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
    side: THREE.FrontSide
  });

  // Plinth top-face gradient #0b0b10 (bottom) to #16161d (top)
  const plinthUV = uv();
  const plinthGradNode = mix(
    new THREE.Color('#0b0b10'),
    new THREE.Color('#16161d'),
    smoothstep(0, 1, plinthUV.y)
  );
  plinthMat.colorNode = plinthGradNode;

  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 - 0.125;
  group.add(plinth);

  // Load the watch mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const watchScene = gltf.scene;

    // Normalize to 2.2 units tall
    const box = new THREE.Box3().setFromObject(watchScene);
    const size = box.getSize(new THREE.Vector3());
    const currentHeight = size.y;
    const scale = currentHeight > 0 ? 2.2 / currentHeight : 1;
    watchScene.scale.multiplyScalar(scale);

    // Center at origin
    box.setFromObject(watchScene);
    const center = box.getCenter(new THREE.Vector3());
    watchScene.position.sub(center);

    // Apply watch material PBR overrides
    watchScene.traverse((child) => {
      if (child.isMesh && child.material) {
        const originalMat = child.material;
        const newMat = new MeshStandardNodeMaterial({
          map: originalMat.map,
          normalMap: originalMat.normalMap,
          roughnessMap: originalMat.roughnessMap,
          metalnessMap: originalMat.metalnessMap,
          emissiveMap: originalMat.emissiveMap,
          emissive: originalMat.emissive || new THREE.Color('#000000'),
          color: originalMat.color || new THREE.Color('#ffffff'),
          roughness: 0.52,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4,
          anisotropy: 0.8,
          anisotropyMap: null,
          side: THREE.FrontSide
        });
        child.material = newMat;
      }
    });

    group.add(watchScene);

    // Create product-group for orbit + depth-rotate
    const productGroup = new THREE.Group();
    productGroup.add(watchScene);
    group.userData.watchScene = watchScene;
    group.userData.productGroup = productGroup;
  });

  // Lighting setup
  // Key light: 1.2 intensity at 30-45 deg
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2.5, 1.5);
  keyLight.castShadow = false;
  group.add(keyLight);

  // Accent rim light: left flank, signal red (#ff2a38), 0.9 intensity
  const rimLight = new THREE.PointLight(0xff2a38, 0.9);
  rimLight.position.set(-2.2, 0.8, 1.2);
  rimLight.distance = 6;
  group.add(rimLight);

  // Fill/ambient (scene-level ambient 0.6 in main renderer; add fill here for local boost)
  const fillLight = new THREE.DirectionalLight(0xffffff, 0.5);
  fillLight.position.set(-0.5, -1, -1);
  group.add(fillLight);

  // Text overlay (positioned in 3D space)
  const textGroup = new THREE.Group();
  group.add(textGroup);

  // Headline: "Calibre NA-01" at y = -1.5 (6 × 0.25 units below scene center)
  const headline = ctx.fontAtlas.createText('Calibre NA-01', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headline.position.set(0, -1.5, 0.2);
  textGroup.add(headline);

  // Body text: "Machined in-house. 41 mm. Grade 5 titanium." at y = -2.0 (0.5 units below headline)
  const bodyText = ctx.fontAtlas.createText('Machined in-house. 41 mm. Grade 5 titanium.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'center'
  });
  bodyText.position.set(0, -2.0, 0.2);
  textGroup.add(bodyText);

  // Caption: "FROM 4200 USD / SHIPS IN 21 DAYS"
  const caption = ctx.fontAtlas.createText('FROM 4200 USD / SHIPS IN 21 DAYS', {
    fontSize: 18,
    color: '#ff2a38',
    align: 'center',
    letterSpacingPx: 1.5
  });
  caption.position.set(0, -2.5, 0.2);
  textGroup.add(caption);

  // Apply cinematic primitives
  // Orbit on load
  const orbitConfig = {
    speed: config.cinematicPrimitives?.find(p => p.name === 'orbit')?.params?.speed ?? 0.15,
    radius: config.cinematicPrimitives?.find(p => p.name === 'orbit')?.params?.radius ?? 0.6
  };

  // Defer orbit setup until watch is loaded
  const checkLoadAndApplyOrbit = setInterval(() => {
    if (group.userData.productGroup) {
      clearInterval(checkLoadAndApplyOrbit);

      const orbitResult = ctx.primitives.orbit(group.userData.productGroup, {
        speed: orbitConfig.speed,
        radius: orbitConfig.radius,
        trigger: 'load'
      });

      if (orbitResult && orbitResult.cleanup) {
        cleanups.push(orbitResult.cleanup);
      }
      if (orbitResult && orbitResult.timeline) {
        timelines.push(orbitResult.timeline);
      }

      // Depth-rotate on hover
      const depthRotateConfig = {
        maxDeg: config.cinematicPrimitives?.find(p => p.name === 'depth-rotate')?.params?.maxDeg ?? 6
      };

      const depthRotateResult = ctx.primitives['depth-rotate'](group.userData.productGroup, {
        maxDeg: depthRotateConfig.maxDeg,
        trigger: 'hover'
      });

      if (depthRotateResult && depthRotateResult.cleanup) {
        cleanups.push(depthRotateResult.cleanup);
      }
      if (depthRotateResult && depthRotateResult.timeline) {
        timelines.push(depthRotateResult.timeline);
      }
    }
  }, 50);

  cleanups.push(() => clearInterval(checkLoadAndApplyOrbit));

  // Fade-in text on entrance
  textGroup.children.forEach((child, i) => {
    child.traverse((mesh) => {
      if (mesh.material) {
        mesh.material.transparent = true;
        mesh.material.opacity = 0;
      }
    });
  });

  const textEntrance = gsap.timeline();
  textGroup.children.forEach((child, i) => {
    textEntrance.to(child, {
      opacity: 1,
      duration: 0.6,
      delay: 0.1 + i * 0.08,
      ease: 'power2.out'
    }, 0);
  });

  timelines.push(textEntrance);

  // User data for cleanup and event handlers
  group.userData.handlers = {
    onHover: (isHovering) => {
      // Depth-rotate primitive handles this via trigger: 'hover'
    }
  };

  group.userData.cleanup = () => {
    // Kill all timelines
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    // Call all cleanup functions
    cleanups.forEach((fn) => {
      if (typeof fn === 'function') fn();
    });

    // Dispose geometries and materials
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
